#nullable enable // autogenerated

using MVZ2.GameContent.Contraptions;
using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Effects;
using MVZ2.GameContent.Enemies;
using MVZ2.GameContent.Shells;
using MVZ2.Vanilla.Callbacks;
using MVZ2.Vanilla.Unlocks;
using MVZ2Logic;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using MVZ2Logic.Modding;
using PVZEngine.Callbacks;
using PVZEngine.Entities;

namespace MVZ2.GameContent.GlobalCallbacks
{
    [ModGlobalCallbacks]
    public class AchievementsGlobalCallbacks : VanillaGlobalCallbacks
    {
        public override void Apply(Mod mod)
        {
            mod.AddTriggerFiltered(LevelCallbacks.POST_ENTITY_DEATH, PostContraptionDeathCallback, filter: EntityTypes.PLANT);
            mod.AddTriggerFiltered(LevelCallbacks.POST_ENTITY_DEATH, PostEnemyDeathCallback, filter: EntityTypes.ENEMY);
            mod.AddTriggerFiltered(VanillaLevelCallbacks.POST_OBSIDIAN_FIRST_AID, PostAnvilObsidianFirstAidCallback, filter: VanillaContraptionID.anvil);
        }
        private void PostContraptionDeathCallback(LevelCallbacks.EntityDeathParams param, CallbackResultVoid result)
        {
            var entity = param.entity;
            var info = param.deathInfo;
            var source = info.Source;
            if (source == null)
                return;
            if (entity.IsHostileEntity() && !entity.Level.IsIZombie())
            {
                var level = entity.Level;
                var killedByFriendlyEnemy = source.IsEntitySpawnedByEntity(level, (s, def) =>
                {
                    if (!level.IsFriendlyFaction(s.Faction))
                        return false;
                    return def.Type == EntityTypes.ENEMY;
                });
                if (killedByFriendlyEnemy)
                {
                    Global.Saves.Unlock(VanillaUnlockID.mesmerisedMatchup);
                    Global.Saves.SaveToFile(); // 完成成就后保存游戏。
                }
            }
        }
        private void PostEnemyDeathCallback(LevelCallbacks.EntityDeathParams param, CallbackResultVoid result)
        {
            var entity = param.entity;
            var info = param.deathInfo;
            if (entity.IsEntityOf(VanillaEnemyID.skeleton) && info.Effects.HasEffect(VanillaDamageEffects.FALL_DAMAGE) && !entity.Level.IsIZombie())
            {
                Global.Saves.Unlock(VanillaUnlockID.bonebreaker);
                Global.Saves.SaveToFile(); // 完成成就后保存游戏。
            }

            var source = info.Source;
            if (source != null)
            {
                if (entity.IsFriendlyEntity() && !entity.Level.IsIZombie())
                {
                    var level = entity.Level;
                    var killedByHostileContraption = source.IsEntitySpawnedByEntity(level, (s, def) => def.Type == EntityTypes.PLANT && level.IsHostileFaction(s.Faction));
                    if (killedByHostileContraption)
                    {
                        Global.Saves.Unlock(VanillaUnlockID.mesmerisedMatchup);
                        Global.Saves.SaveToFile(); // 完成成就后保存游戏。
                    }
                }

                // 重力板化
                if (entity.GetShellID() == VanillaShellID.metal && source is EntitySourceReference entitySource && entitySource.DefinitionID == VanillaContraptionID.goldenApple)
                {
                    if (info.HasEffect(VanillaDamageEffects.THROWN))
                    {
                        Global.Saves.Unlock(VanillaUnlockID.gravityPadded);
                        Global.Saves.SaveToFile(); // 完成成就后保存游戏。
                    }
                }
            }
        }
        private void PostAnvilObsidianFirstAidCallback(EntityCallbackParams param, CallbackResultVoid result)
        {
            Global.Saves.Unlock(VanillaUnlockID.reforged);
            Global.Saves.SaveToFile(); // 完成成就后保存游戏。
        }
    }
}
